package br.com.conectatea.sessao.domain; import br.com.conectatea.shared.domain.AuditableEntity; import jakarta.persistence.*; import java.time.OffsetDateTime; @Entity @Table(name="sessoes") public class Sessao extends AuditableEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="data_hora") private OffsetDateTime dataHora; private int duracao; @Enumerated(EnumType.STRING) private StatusSessao status; @Enumerated(EnumType.STRING) private TipoSessao tipo; @Column(columnDefinition="text") private String descricao; @Column(columnDefinition="text") private String observacoes; @Column(name="crianca_id") private Long criancaId; @Column(name="profissional_id") private Long profissionalId; protected Sessao(){} public Sessao(OffsetDateTime d,int duration,TipoSessao t,String desc,String obs,Long child,Long prof){dataHora=d;duracao=duration;tipo=t;descricao=desc;observacoes=obs;criancaId=child;profissionalId=prof;status=StatusSessao.AGENDADA;} public Long getId(){return id;} public OffsetDateTime getDataHora(){return dataHora;} public int getDuracao(){return duracao;} public StatusSessao getStatus(){return status;} public TipoSessao getTipo(){return tipo;} public String getDescricao(){return descricao;} public String getObservacoes(){return observacoes;} public Long getCriancaId(){return criancaId;} public void update(OffsetDateTime d,int du,TipoSessao t,String de,String o){dataHora=d;duracao=du;tipo=t;descricao=de;observacoes=o;} public void status(StatusSessao s){status=s;} }
